def variants(shape):
 s=set(shape); out=[]
 for refl in [False,True]:
  for k in range(4):
   pts=[]
   for x,y in s:
    if refl:y=-y
    for _ in range(k): x,y=y,-x
    pts.append((x,y))
   minx=min(x for x,y in pts);miny=min(y for x,y in pts)
   ns=frozenset((x-minx,y-miny) for x,y in pts)
   if ns not in out:out.append(ns)
 return out

